const CENTRAL_BOARD_ID = "18413271331";

// As paginas vem do no de leitura (que agora so traz itens); os updates vem de um no
// proprio. Ate 18/08 os updates viajavam DENTRO da query paginada — 100 updates com
// replies em toda pagina — e era o que estourava o orcamento de complexidade do Monday
// na terceira pagina: 200 com errors[], cursor sumia, e a leitura terminava "completa"
// com 1146 de 1620 itens (14/08/2026).
const pages = $('Ler board central e updates').all().map(item => item.json);

// Erro no CORPO (o Monday nao usa status HTTP pra isso) para a virada aqui, antes de
// qualquer passo destrutivo.
const paginaComErro = pages.findIndex(p => p && p.errors);
if (paginaComErro !== -1) {
  throw new Error('Monday devolveu errors[] na pagina ' + (paginaComErro + 1) + ' da leitura: ' + JSON.stringify(pages[paginaComErro].errors));
}

const firstBoard = pages.find(page => page.data?.boards?.[0])?.data?.boards?.[0];
if (!firstBoard) throw new Error("Board central de producao nao encontrado ou nao esta ativo: " + CENTRAL_BOARD_ID);
const itemsById = new Map();
for (const page of pages) {
  const board = page.data?.boards?.[0];
  for (const item of board?.items_page?.items || []) itemsById.set(String(item.id), item);
}

// ── TRAVA DE LEITURA PARCIAL (17/08/2026) ────────────────────────────────────
// A virada de 14/08 leu 1146 de ~1620 itens e seguiu: arquivou so o que leu, o
// repovoamento criou 1039 por cima, e sobraram 441 pessoas duplicadas em setembro
// (SEMSA 216, CETAM 94, APRENDIZ 50, SEDUC INTERIOR 40...).
const totalReal = Number(firstBoard.items_count ?? -1);
if (totalReal < 0) {
  throw new Error('Board nao devolveu items_count — nao da pra provar que a leitura foi completa. Abortando.');
}
if (itemsById.size !== totalReal) {
  throw new Error(
    'LEITURA PARCIAL: li ' + itemsById.size + ' itens de ' + totalReal + ' no board ' + CENTRAL_BOARD_ID +
    '. Arquivar so os lidos deixaria ' + (totalReal - itemsById.size) + ' itens antigos no board, e o ' +
    'repovoamento criaria duplicata de cada um. Corrigir a paginacao antes de rodar.'
  );
}

// Updates: no proprio, fora da paginacao.
const upsResp = $('Ler updates do board central').first().json;
if (upsResp && upsResp.errors) {
  throw new Error('Monday devolveu errors[] na leitura dos updates: ' + JSON.stringify(upsResp.errors));
}
const updates = upsResp?.data?.boards?.[0]?.updates || [];

const formatBoardName = (date) => {
  const mm = String(date.getMonth() + 1).padStart(2, "0");
  const yy = String(date.getFullYear()).slice(-2);
  return `${mm}/${yy} - Plan. de Benef\u00edcio - Contato`;
};

const now = new Date();
const currentMonth = new Date(now.getFullYear(), now.getMonth(), 1);
const nextMonth = new Date(now.getFullYear(), now.getMonth() + 1, 1);

return [{
  json: {
    centralBoardId: CENTRAL_BOARD_ID,
    currentBoardName: firstBoard.name,
    archiveBoardName: formatBoardName(currentMonth),
    nextBoardName: formatBoardName(nextMonth),
    updates,
    itemIdsToArchive: Array.from(itemsById.keys()),
    itemCountToArchive: itemsById.size,
    updateCountToCopy: updates.length,
    itemPagesRead: pages.length
  }
}];

const prep = $("Preparar dados da virada").first().json;
const duplicateBoard = $("Duplicar board central").first().json.data?.duplicate_board?.board;
if (!duplicateBoard?.id) throw new Error("Nao foi possivel obter o ID do board duplicado.");
return (prep.updates || []).map((update, index) => {
  const replies = update.replies || [];
  const creator = update.creator?.name || "Autor nao informado";
  const replyHtml = replies.length ? `<hr><p><strong>Respostas copiadas:</strong></p>${replies.map(reply => {
    const replyCreator = reply.creator?.name || "Autor nao informado";
    const replyBody = reply.body || `<p>${reply.text_body || ""}</p>`;
    return `<blockquote><p><strong>${replyCreator}</strong> em ${reply.created_at || "data nao informada"}</p>${replyBody}</blockquote>`;
  }).join("")}` : "";
  return { json: { duplicateBoardId: duplicateBoard.id, sourceUpdateId: update.id, body: `<p><strong>Mensagem copiada do bal\u00e3o central</strong></p><p>Autor original: ${creator}<br>Data original: ${update.created_at || "data nao informada"}<br>Update original: ${update.id}</p><hr>${update.body || `<p>${update.text_body || ""}</p>`}${replyHtml}`, index } };
});

const prep = $("Preparar dados da virada").first().json;
const ids = prep.itemIdsToArchive || [];
// Sempre emite >=1 item: se nao ha nada pra arquivar, manda sentinela pro IF desviar
if (ids.length === 0) return [{ json: { __semArquivar: true, centralBoardId: prep.centralBoardId } }];
return ids.map(itemId => ({ json: { itemId, centralBoardId: prep.centralBoardId } }));

const TARGET_BOARD_ID = "18413271331";
const BATCH_SIZE = 25;
const mainBoardId = TARGET_BOARD_ID;

// Datas no padrao DD/MM/YYYY (aceita ISO "YYYY-MM-DD...", ja "DD/MM/YYYY", ou vazio)
const formatDate = (value) => {
  if (!value) return "";
  const s = String(value).trim();
  const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return `${iso[3]}/${iso[2]}/${iso[1]}`;
  const br = s.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
  if (br) return `${br[1]}/${br[2]}/${br[3]}`;
  return s.substring(0, 10);
};

// Ferias e atestado NAO sao mais gravados pela virada (decisao 19/07/2026):
// ferias vem do RM (BEN.FER) e eventos do Nexti, ambos pela automacao de apuracao.
// Janela de apuracao aprovada: [16 do mes anterior, 15 do mes atual]
const atestadoWindow = () => {
  const now = new Date();
  const start = new Date(now.getFullYear(), now.getMonth() - 1, 16);
  const end = new Date(now.getFullYear(), now.getMonth(), 15);
  return [start, end];
};
const parseBR = (s) => {
  const m = String(s || "").match(/(\d{2})\/(\d{2})\/(\d{4})/);
  return m ? new Date(+m[3], +m[2] - 1, +m[1]) : null;
};
// Filtra a lista bruta de periodos (do RM) para os que tocam a janela da competencia
const filterAtestado = (raw) => {
  if (!raw) return "";
  const [ws, we] = atestadoWindow();
  return String(raw).split(";").map(s => s.trim()).filter(Boolean).filter(p => {
    const parts = p.split(" a ");
    const ini = parseBR(parts[0]);
    const fim = parseBR(parts[1] || parts[0]);
    return ini && fim && ini <= we && fim >= ws;
  }).join("; ");
};

const normalize = (value) => String(value || "")
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .replace(/\s+/g, " ")
  .trim()
  .toUpperCase();

// Secoes de 3 segmentos (8 digitos) nao passam pelo parser posicional — ver o bloco
// "CODIGO DE SECAO CURTO" em resolveGroupId.
const SECOES_CURTAS = {
  "01010004": "group_mm4ndjtw"   // 01.01.0004 = BARCO CARTUZINHO (MILTON SERGIO, chapa 000047)
};

const groupIds = {
  "04": "group_mm2edhx5",
  "05": "group_mm464byh",
  "07": "group_mm2eyxfg",
  "07|6": "group_mm5a9g2e",   // JCF -> "07 - ADM JCF"
  "07.03": "group_mm2eprpn",   // 07.03 - INSTITUTO PCD
  "10": "group_mm2ef8mn",
  "11.01": "group_mm2e99p9",
  "11.02": "group_mm2e4kex",
  "15": "group_mm2em803",
  "74": "group_mm2ext7q",
  "78": "group_mm2eknpq",
  "79": "group_mm2enj5b",
  "84": "group_mm2eczww",
  "85": "group_mm2e22nj",
  "AFASTADOS": "group_mm464byh",
  "CONTRATOS_TRANSICAO": "group_mm464byh"
};

const getValue = (data, normalizedNames) => {
  for (const normalizedName of normalizedNames) {
    for (const [key, value] of Object.entries(data)) {
      if (normalize(key) === normalizedName && value !== undefined && value !== null && String(value).trim() !== "") {
        return value;
      }
    }
  }
  return "";
};

const employeeName = (data) => getValue(data, ["NOME DO FUNCIONARIO", "FUNCIONARIO"]) || "Sem nome";

const resolveGroupId = (data) => {
  const coligada = String(getValue(data, ["CODCOLIGADA", "CODIGO COLIGADA", "COLIGADA", "COD. COLIGADA"])).replace(/\D/g, "");

  // Regra: TODOS os funcionarios da coligada 6 vao para o grupo JCF (07 - ADM JCF)
  if (coligada === "6") return groupIds["07|6"];

  const unidade = normalize(getValue(data, ["LOCAL/UNIDADE"]));
  if (["AFASTADO INSS", "LICENCA MATERNIDADE", "LICENCA SEM VENCIMENTO", "RESCISAO INDIRETA"].includes(unidade)) {
    return groupIds.AFASTADOS;
  }
  if (unidade.includes("CONTRATOS EM TRANSICAO")) {
    return groupIds.CONTRATOS_TRANSICAO;
  }

  const codeRaw = getValue(data, ["CODIGO", "CODIGO DA SECAO", "CODSECAO", "COD. SECAO"]);
  const digits = String(codeRaw || "").replace(/\D/g, "");
  if (digits.length < 8) throw new Error(`Codigo de secao invalido ou curto para ${employeeName(data)}: ${codeRaw || "vazio"}`);


  // ── CODIGO DE SECAO CURTO (bug achado em 20/08/2026) ────────────────────────
  // O parser abaixo e POSICIONAL e assume 5 segmentos (14 digitos):
  //   01.01.0015.01.0001 -> base = digits[6..8] = "15" -> 15 - BARCO CONTATO    OK
  // Com 3 segmentos (8 digitos) ele le os dois ultimos digitos do TERCEIRO campo
  // como se fosse o codigo do contrato:
  //   01.01.0004 -> base = "04" -> 04 - DETRAN                                  ERRADO
  // Foi o que jogou o MILTON SERGIO (BARCO CARTUZINHO, chapa 000047) no DETRAN, e com
  // as regras de calculo do DETRAN (grupo C) em vez das do Cartuzinho (grupo F). O DP
  // vinha consertando na mao: em 08/26 a linha dele era "MILTON ... (copy)".
  // Unidade nao desempata: ADRIANO e NIVALDO tambem sao unidade BARCO e pertencem ao
  // 15 - BARCO CONTATO. Quem distingue e a secao: 0004 = Cartuzinho, 0015 = Contato.
  // Sao 8 linhas de codigo curto em 1319. Codigo curto desconhecido cai no COMPLEMENTAR
  // CONTADO — nunca num contrato escolhido por acidente de posicao.
  if (digits.length !== 14) {
    const curto = SECOES_CURTAS[digits];
    if (curto) return curto;
    pulados.codigoCurto++;
    return "group_mm464byh";
  }
  const base = digits.substring(6, 8);
  const branch = digits.substring(8, 10);

  if (base === "07" && branch === "03") return groupIds["07.03"];   // INSTITUTO PCD = branch 03 (corrigido; antes estava "02")
  if (base === "07") return groupIds["07"];
  if (base === "11" && branch === "01") return groupIds["11.01"];
  if (base === "11" && branch === "02") return groupIds["11.02"];

  const groupId = groupIds[base];
  if (!groupId) return "group_mm464byh"; // rede de seguranca: secao sem grupo mapeado cai neste grupo
  return groupId;
};

const mapSituacao = (data) => {
  const situacao = getValue(data, ["SITUACAO"]);
  if (normalize(situacao) === "APOS. POR INCAPACIDADE PERMANENTE") return "Af.Previdência";
  return situacao;
};

const collaborators = [];
// Contadores de quem NAO entra — a virada precisa dizer o que descartou. Ate 18/08 esses
// numeros nao existiam: quem caia fora sumia calado.
const pulados = { intermitente: 0, coligada: 0, afastadoInss: 0, rescisaoIndireta: 0, diretoria: 0, codigoCurto: 0 };

// ── QUEM NAO ENTRA NO BOARD (regra do DP, 19/08/2026) ────────────────────────
// AFASTADO INSS e RESCISAO INDIRETA nao recebem beneficio e nao devem ter linha.
// Isso ja acontecia na pratica, mas por BUG: essas secoes apontavam para os grupos
// mortos group_mm3c4xaq / group_mm58q50d, o Monday recusava o lote inteiro com
// "Group not found" e as pessoas evaporavam junto com quem estava no mesmo lote de 25.
// Corrigir o mapa de grupo (17/08) fez elas voltarem a nascer — o oposto do desejado.
// Agora a exclusao e explicita e contada.
const UNIDADES_FORA = ["AFASTADO INSS", "RESCISAO INDIRETA"];

for (const item of $input.all()) {
  const data = item.json;
  const intermitente = normalize(getValue(data, ["INTERMITENTE?"]));
  if (intermitente === "SIM") { pulados.intermitente++; continue; }

  // "Intermitente?" e TIPO DE CONTRATO, nao um sim/nao: os valores reais medidos em
  // 19/08 sao "Trabalhador" (1106), "SIM" (145), "Empregado - Aprendiz" (52) e
  // "Estagiario" (16). So "SIM" marca intermitente.

  // DIRETORIA nao entra (decisao 20/08/2026): o corte e por FUNCAO, nao por unidade.
  // Por unidade cairia junto a REBECA (ASSISTENTE DE DIRETORIA II, unidade DIRETORIA EXECUTIVA),
  // que e funcionaria normal e recebe. Por funcao pega exatamente os 3: THAIS (chapa 000048) e
  // CARLOS ARTUR, que tem DUAS chapas no RM (000049 coligada 1 + 003931 coligada 3) e por isso
  // nascia com linha DOBRADA — VR/VT em dobro pra mesma pessoa.
  // ASSISTENTE DE DIRETORIA nao casa com startsWith(DIRETOR).
  if (normalize(getValue(data, ["FUNCAO"])).startsWith("DIRETOR")) { pulados.diretoria++; continue; }

  const unidadeFora = normalize(getValue(data, ["LOCAL/UNIDADE"]));
  if (UNIDADES_FORA.includes(unidadeFora)) {
    if (unidadeFora === "AFASTADO INSS") pulados.afastadoInss++; else pulados.rescisaoIndireta++;
    continue;
  }

  // Filtro de contratos: apenas coligadas 1, 3 e 6 (ignora as demais, ex.: coligada 2 SEJUSC)
  const coligadaAtual = String(getValue(data, ["CODCOLIGADA", "CODIGO COLIGADA", "COLIGADA", "COD. COLIGADA"])).replace(/\D/g, "");
  if (!["1", "3", "6"].includes(coligadaAtual)) { pulados.coligada++; continue; }

  const columnValues = {
    "texto": getValue(data, ["FUNCIONARIO", "NOME DO FUNCIONARIO"]),
    "dup__of_matr_cula": getValue(data, ["CPF"]),
    "texto75": getValue(data, ["LOCAL/UNIDADE"]),
    "text_mkrzbj02": getValue(data, ["CAMPO COMPLEMENTAR"]),
    "text_mkrztp4t": getValue(data, ["JORNADA"]),
    "texto0": getValue(data, ["FUNCAO"]),
    "texto8": formatDate(getValue(data, ["ADMISSAO"])),
    "texto92": getValue(data, ["INTERMITENTE?"]),
    "text_mkt63tyk": getValue(data, ["CODIGO"]),
    "optante___vt": { "label": getValue(data, ["VALE TRANSPORTE"]) || "NÃO" },
    "status__1": { "label": getValue(data, ["FUNCIONARIO DEFICIENTE"]) || "NÃO" },
    "status2__1": { "label": mapSituacao(data) }
  };

  collaborators.push({
    groupId: resolveGroupId(data),
    itemName: employeeName(data),
    columnValuesString: JSON.stringify(columnValues)
  });
}

// ── GUARDA DE GRUPO (17/08/2026) ─────────────────────────────────────────────
// O mapa secao->grupo e CHUMBADO e envelhece. Em 08/26 quatro ids estavam mortos; o
// pior foi o ADM JCF: 49 pessoas da coligada 6 mandadas pra group_mm2n79cm, que nao
// existe. O Monday responde 200 com errors[] e o no HTTP marca success, entao elas
// sumiram caladas (46 em agosto -> 0 em setembro).
//
// Confere cada group_id resolvido contra os grupos REAIS do board (lidos no inicio do
// WF). Id morto passa a PARAR a virada em vez de evaporar gente.
const gruposReais = new Set(
  $('Ler board central e updates').all()
    .flatMap(i => (i.json && i.json.data && i.json.data.boards && i.json.data.boards[0] && i.json.data.boards[0].groups) || [])
    .map(g => String(g.id))
);
if (gruposReais.size === 0) {
  throw new Error('Nao consegui ler os grupos do board — sem isso o mapa de grupo nao pode ser validado. Abortando.');
}
const usadosPorGrupo = new Map();
for (const col of collaborators) {
  const gid = String(col.groupId || '');
  if (!usadosPorGrupo.has(gid)) usadosPorGrupo.set(gid, { exemplo: col.itemName || '?', qtd: 0 });
  usadosPorGrupo.get(gid).qtd++;
}
const gruposInvalidos = [...usadosPorGrupo.entries()].filter(([gid]) => !gruposReais.has(gid));
if (gruposInvalidos.length) {
  throw new Error(
    'GRUPO INEXISTENTE no board ' + mainBoardId + ': ' +
    gruposInvalidos.map(([gid, v]) => gid + ' (' + v.qtd + ' pessoas, ex: ' + v.exemplo + ')').join(' | ') +
    '. Mapa secao->grupo desatualizado — corrigir antes de rodar, senao essas pessoas somem sem aviso.'
  );
}

const output = [];
for (let start = 0; start < collaborators.length; start += BATCH_SIZE) {
  const batch = collaborators.slice(start, start + BATCH_SIZE);
  const declarations = ["$boardId: ID!"];
  const mutations = ["complexity { before after query }"];
  const variables = { boardId: mainBoardId };

  batch.forEach((collaborator, index) => {
    declarations.push(`$groupId${index}: String!`, `$itemName${index}: String!`, `$columnValues${index}: JSON!`);
    mutations.push(`item${index}: create_item(board_id: $boardId, group_id: $groupId${index}, item_name: $itemName${index}, column_values: $columnValues${index}, create_labels_if_missing: true) { id }`);
    variables[`groupId${index}`] = collaborator.groupId;
    variables[`itemName${index}`] = collaborator.itemName;
    variables[`columnValues${index}`] = collaborator.columnValuesString;
  });

  output.push({
    json: {
      boardId: mainBoardId,
      batchNumber: output.length + 1,
      batchSize: batch.length,
      totalCollaborators: collaborators.length,
      pulados,
      query: `mutation CreateCollaboratorsBatch(${declarations.join(", ")}) { ${mutations.join(" ")} }`,
      variables
    }
  });
}

return output;

const prep = $("Preparar dados da virada").first().json;
const duplicateBoard = $("Duplicar board central").first().json.data?.duplicate_board?.board;
const conf = $("Conferir colaboradores").first().json;
let lotesGravados = 0, colaboradoresCriados = 0;
try {
  const lotes = $("Conferir lote de criacao").all();
  lotesGravados = lotes.length;
  colaboradoresCriados = lotes.reduce((s, i) => s + (i.json.criados || 0), 0);
} catch (e) { /* nenhum lote gravado */ }
return [{ json: {
  ok: true,
  centralBoardId: prep.centralBoardId,
  duplicateBoardId: duplicateBoard?.id,
  duplicateBoardName: duplicateBoard?.name,
  nextBoardName: prep.nextBoardName,
  updatesCopied: prep.updateCountToCopy,
  itemPagesRead: prep.itemPagesRead,
  itemsArchivedRequested: prep.itemCountToArchive,
  colaboradoresEsperados: conf?.total,
  // quem o BENAUT trouxe e a virada NAO criou, por regra — nao pode ser silencioso
  descartados: conf?.pulados || null,
  lotesGravados,
  colaboradoresCriados
} }];

// TRAVA (17/08/2026): o Monday responde HTTP 200 com `errors[]` e o no HTTP marca
// success. Foi assim que a virada dos intermitentes renomeou e arquivou um board sem
// ter duplicado nada. Nada depois daqui roda sem a copia existir.
const r = $('Duplicar board central').first().json;
if (r && r.errors) throw new Error('Monday recusou a duplicacao: ' + JSON.stringify(r.errors));
const b = r && r.data && r.data.duplicate_board && r.data.duplicate_board.board;
if (!b || !b.id) throw new Error('Duplicacao nao devolveu board id — abortando ANTES de arquivar/renomear.');
return [{ json: { copiaBoardId: String(b.id), copiaBoardName: b.name || null } }];

// Piso de sanidade ANTES de qualquer passo destrutivo.
// Em 14/08/2026 a virada duplicou, arquivou e renomeou primeiro e so depois consultou o
// RM — o mesmo defeito que fez o board de julho dos intermitentes nascer vazio. Agora o
// RM vem primeiro e este no confere que a lista tem tamanho de gente de verdade.
const PISO = 850; // medido 19/08/2026: 1169 elegiveis - 63 de afastado/rescisao = ~1106
const lotes = $input.all();
const total = lotes.reduce((s, i) => s + (i.json.batchSize || 0), 0);
const pulados = lotes[0]?.json?.pulados || {};
const ok = total >= PISO;
return [{ json: {
  ok, total, piso: PISO, lotes: lotes.length, pulados,
  motivo: ok ? null : `lista de colaboradores veio com ${total} (piso ${PISO}) — ponte AIONS instavel ou consulta BENAUT mudou`,
} }];

