// 'Preparar colaboradores para o board central' agora roda LA NA FRENTE (antes de
// destruir qualquer coisa). O caminho principal segue com 1 item so (a conferencia do
// piso), entao aqui recuperamos os lotes para alimentar o loop de criacao.
return $('Preparar colaboradores para o board central').all();

// O Monday responde HTTP 200 com errors[] quando estoura o orcamento de complexidade
// ou o group_id nao existe — e o no HTTP marca success. Foi assim que os 47 lotes de
// 14/08/2026 sumiram calados e o "07 - ADM JCF" ficou com ZERO pessoa em setembro.
const r = $input.first().json;
if (r && r.errors) {
  const txt = JSON.stringify(r.errors);
  const complexidade = txt.includes('COMPLEXITY_BUDGET_EXHAUSTED');
  throw new Error(
    'Monday recusou o lote de create_item (o no HTTP marcou success): ' + txt +
    (complexidade ? ' | orcamento de complexidade estourado — nao ler board cheio enquanto a virada grava; esperar e redisparar' : '')
  );
}
const data = (r && r.data) || {};
const chaves = Object.keys(data).filter(k => /^item\d+$/.test(k));
if (chaves.length === 0) {
  throw new Error('Lote nao criou nenhum item — resposta inesperada do Monday: ' + JSON.stringify(r).slice(0, 300));
}
const criados = chaves.filter(k => data[k] && data[k].id).length;
if (criados < chaves.length) {
  throw new Error('Lote PARCIAL: ' + criados + ' de ' + chaves.length + ' create_item voltaram id.');
}
return [{ json: { criados, complexity: data.complexity || null } }];
